#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Generate the canonical field descriptors and reference table."""

import json
from collections.abc import Sequence
from pathlib import Path

import emit


def outputs(root: Path) -> dict[str, str]:
    catalog = json.loads((root / "catalog/fields.json").read_text())
    code = [
        "(* Generated by scripts/generate/generate_fields.py from catalog/fields.json. *)"
    ]
    docs = [
        "# Captured fields",
        "",
        "All fields below are acquired by the core snapshot schema on supported tmux releases.",
        "Text operations compare bytes without normalization or case folding.",
        "",
        "| OCaml field | Value | tmux format |",
        "| --- | --- | --- |",
    ]
    types = {"Bool": "bool", "Int": "int", "Text": "string"}
    for module, fields in catalog.items():
        code.append(f"module {module} = struct")
        for field, (kind, name, *accessor) in fields.items():
            get = accessor[0] if accessor else f"Graph.{module}.{field}"
            code.append(
                f'let {field} = Filter.Field.{{name = "{name}"; kind = {kind}; get = {get}}}'
            )
            docs.append(f"| `{module}.Fields.{field}` | `{types[kind]}` | `{name}` |")
        code.append(
            "let fields = ["
            + "; ".join(f"Filter.Field.Pack {name}" for name in fields)
            + "]"
        )
        code.append("end")
    formatted = emit.ocamlformat(
        root, "lib/generated_fields.ml", "\n".join(code) + "\n"
    )
    return {
        "lib/generated_fields.ml": formatted,
        "docs/fields.md": "\n".join(docs) + "\n",
    }


def main(argv: Sequence[str] | None = None, root: Path = emit.ROOT) -> None:
    emit.main(__doc__ or "", outputs, argv=argv, root=root)


if __name__ == "__main__":
    main()
